PRAGMA foreign_keys=ON; PRAGMA busy_timeout=5000; PRAGMA journal_mode=WAL;
 CREATE TABLE IF NOT EXISTS migrations(version INTEGER PRIMARY KEY);
 CREATE TABLE IF NOT EXISTS principals(id TEXT PRIMARY KEY, tenant TEXT NOT NULL, role TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1);
 CREATE TABLE IF NOT EXISTS agents(id TEXT PRIMARY KEY, actions TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1);
 CREATE TABLE IF NOT EXISTS policy(id INTEGER PRIMARY KEY CHECK(id=1), version INTEGER NOT NULL);
 INSERT OR IGNORE INTO policy VALUES(1,1);
 CREATE TABLE IF NOT EXISTS resources(tenant TEXT NOT NULL,id TEXT NOT NULL,kind TEXT NOT NULL,owner TEXT NOT NULL,body TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(tenant,id));
 CREATE TABLE IF NOT EXISTS runs(id TEXT PRIMARY KEY,tenant TEXT NOT NULL,user_id TEXT NOT NULL,agent TEXT NOT NULL,scopes TEXT NOT NULL,status TEXT NOT NULL,expires INTEGER NOT NULL,steps INTEGER NOT NULL DEFAULT 0,workdir TEXT NOT NULL,audience TEXT NOT NULL DEFAULT 'agentgate-tools',auto_finish INTEGER NOT NULL DEFAULT 0);
 CREATE TABLE IF NOT EXISTS actions(id TEXT PRIMARY KEY,tenant TEXT NOT NULL,user_id TEXT NOT NULL,run_id TEXT NOT NULL,tool TEXT NOT NULL,params TEXT NOT NULL,digest TEXT NOT NULL,status TEXT NOT NULL,expires INTEGER NOT NULL,idem TEXT NOT NULL,result TEXT NOT NULL DEFAULT '',UNIQUE(tenant,user_id,idem));
 CREATE TABLE IF NOT EXISTS audit(seq INTEGER PRIMARY KEY AUTOINCREMENT,at INTEGER NOT NULL,request_id TEXT NOT NULL,tenant TEXT NOT NULL,user_id TEXT NOT NULL,agent TEXT NOT NULL,run_id TEXT NOT NULL,resource TEXT NOT NULL,action TEXT NOT NULL,policy_version INTEGER NOT NULL,outcome TEXT NOT NULL,action_id TEXT NOT NULL);
 INSERT OR IGNORE INTO migrations VALUES(1);
 UPDATE runs SET status='interrupted' WHERE status='running';
